    "maintenanceSection3Desc": "ഇത് സാധാരണ തേയ്മാനങ്ങൾ ഉൾക്കൊള്ളുന്നു. മനഃപൂർവമായ നാശനഷ്ടങ്ങൾ ഇതിൽ ഉൾപ്പെടുന്നില്ല.",
